import{_ as i,o as n,c as t,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"ioBroker Blockly","description":"Einführung in Blockly des ioBroker-JavaScript-Adapters mit einem offiziellen Einstiegsbeispiel.","frontmatter":{"title":"ioBroker Blockly","description":"Einführung in Blockly des ioBroker-JavaScript-Adapters mit einem offiziellen Einstiegsbeispiel."},"headers":[],"relativePath":"blog/snippets/iobroker-blockly.md","filePath":"blog/snippets/iobroker-blockly.md","lastUpdated":1793113714000}'),a={name:"blog/snippets/iobroker-blockly.md"};function l(s,e,o,d,p,c){return n(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="iobroker-blockly" tabindex="-1">ioBroker Blockly <a class="header-anchor" href="#iobroker-blockly" aria-label="Permalink to &quot;ioBroker Blockly&quot;">​</a></h1><p>Blockly ist der grafische Skripteditor des <strong>ioBroker-JavaScript-Adapters</strong>. Automationen werden aus Blöcken zusammengesetzt, ohne dass der JavaScript-Code vollständig von Hand geschrieben werden muss.</p><div class="info custom-block"><p class="custom-block-title">Offizielle Dokumentation</p><p>Diese Seite gibt nur einen kurzen Einstieg. Die vollständige Beschreibung aller Blöcke und weitere Beispiele befinden sich in der offiziellen ioBroker-Dokumentation.</p></div><h2 id="offizielle-quellen" tabindex="-1">Offizielle Quellen <a class="header-anchor" href="#offizielle-quellen" aria-label="Permalink to &quot;Offizielle Quellen&quot;">​</a></h2><ul><li><a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noreferrer">ioBroker.javascript – offizielles Repository</a></li><li><a href="https://github.com/ioBroker/ioBroker.javascript/tree/master/docs/de" target="_blank" rel="noreferrer">Deutsche Dokumentation des JavaScript-Adapters</a></li><li><a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/docs/de/blockly.md" target="_blank" rel="noreferrer">Vollständige Blockly-Dokumentation</a></li></ul><h2 id="beispiel-1-datenpunkt-abhangig-von-einem-anderen-datenpunkt-schalten" tabindex="-1">Beispiel 1: Datenpunkt abhängig von einem anderen Datenpunkt schalten <a class="header-anchor" href="#beispiel-1-datenpunkt-abhangig-von-einem-anderen-datenpunkt-schalten" aria-label="Permalink to &quot;Beispiel 1: Datenpunkt abhängig von einem anderen Datenpunkt schalten&quot;">​</a></h2><p>Das offizielle Einstiegsbeispiel zeigt eine typische Bewegungserkennung:</p><ul><li>Ein Bewegungs-Datenpunkt dient als Auslöser.</li><li>Bei einer Zustandsänderung wird ein Licht-Datenpunkt gesteuert.</li><li>Der aktuelle Wert des Bewegungsmelders wird an den Licht-Datenpunkt weitergegeben.</li><li>Bewegung schaltet das Licht ein.</li><li>Keine Bewegung schaltet das Licht wieder aus.</li></ul><p><a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/docs/de/blockly.md#beispiel-1" target="_blank" rel="noreferrer"><img src="https://raw.githubusercontent.com/ioBroker/ioBroker.javascript/master/docs/de/img/getting_started_1_de.png" alt="Offizielles ioBroker-Blockly-Beispiel 1"></a></p><small> Bildquelle und Rechtehinweis: Das Bild stammt aus dem offiziellen <a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noopener">ioBroker.javascript-Repository</a>. Die Rechte und Lizenzbedingungen richten sich nach dem dort veröffentlichten Projekt und dessen Lizenz. </small><h2 id="benotigte-blockly-blocke" tabindex="-1">Benötigte Blockly-Blöcke <a class="header-anchor" href="#benotigte-blockly-blocke" aria-label="Permalink to &quot;Benötigte Blockly-Blöcke&quot;">​</a></h2><h3 id="_1-trigger" tabindex="-1">1. Trigger <a class="header-anchor" href="#_1-trigger" aria-label="Permalink to &quot;1. Trigger&quot;">​</a></h3><p>Aus dem Bereich <strong>Trigger</strong> wird der Block <strong>Falls Objekt</strong> verwendet.</p><p>Dort wird der Datenpunkt des Bewegungsmelders ausgewählt.</p><h3 id="_2-datenpunkt-steuern" tabindex="-1">2. Datenpunkt steuern <a class="header-anchor" href="#_2-datenpunkt-steuern" aria-label="Permalink to &quot;2. Datenpunkt steuern&quot;">​</a></h3><p>Aus dem Bereich <strong>System</strong> wird der Block <strong>Steuere</strong> eingefügt.</p><p>Als Ziel wird der Datenpunkt des Lichts ausgewählt.</p><h3 id="_3-wert-ubernehmen" tabindex="-1">3. Wert übernehmen <a class="header-anchor" href="#_3-wert-ubernehmen" aria-label="Permalink to &quot;3. Wert übernehmen&quot;">​</a></h3><p>In den Steuere-Block wird <strong>Wert von Objekt-ID</strong> eingesetzt.</p><p>Dort wird erneut der Bewegungs-Datenpunkt ausgewählt. Dadurch übernimmt das Licht den aktuellen Wahr/Falsch-Zustand des Bewegungsmelders.</p><h2 id="vereinfachter-ablauf" tabindex="-1">Vereinfachter Ablauf <a class="header-anchor" href="#vereinfachter-ablauf" aria-label="Permalink to &quot;Vereinfachter Ablauf&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Falls sich der Bewegungsmelder ändert</span></span>
<span class="line"><span>    setze den Zustand des Lichts</span></span>
<span class="line"><span>    auf den aktuellen Wert des Bewegungsmelders</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="blockly-importieren" tabindex="-1">Blockly importieren <a class="header-anchor" href="#blockly-importieren" aria-label="Permalink to &quot;Blockly importieren&quot;">​</a></h2><p>Den vollständigen importierbaren XML-Code stellt die offizielle Dokumentation direkt unter <strong>Beispiel 1</strong> bereit:</p><p><a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/docs/de/blockly.md#beispiel-1" target="_blank" rel="noreferrer">Beispiel 1 mit Blockly-XML öffnen</a></p><p>Dort kann der XML-Code kopiert und im Blockly-Editor über die Importfunktion eingefügt werden.</p><h2 id="weitere-offizielle-beispiele" tabindex="-1">Weitere offizielle Beispiele <a class="header-anchor" href="#weitere-offizielle-beispiele" aria-label="Permalink to &quot;Weitere offizielle Beispiele&quot;">​</a></h2><p>Die offizielle Dokumentation enthält zusätzlich:</p><ul><li><strong>Beispiel 2:</strong> Licht bei Bewegung einschalten und nach zehn Minuten ohne weitere Bewegung wieder ausschalten.</li><li><strong>Beispiel 3:</strong> E-Mail senden, wenn die Außentemperatur einen Grenzwert überschreitet.</li></ul><p><a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/docs/de/blockly.md#getting-started" target="_blank" rel="noreferrer">Alle offiziellen Blockly-Beispiele ansehen</a></p><h2 id="eigene-blockly-beitrage-im-blog" tabindex="-1">Eigene Blockly-Beiträge im Blog <a class="header-anchor" href="#eigene-blockly-beitrage-im-blog" aria-label="Permalink to &quot;Eigene Blockly-Beiträge im Blog&quot;">​</a></h2><p>Für eigene Beispiele empfiehlt sich folgender Aufbau:</p><ol><li>Aufgabe beschreiben</li><li>benötigte Objekt-IDs nennen</li><li>Screenshot des Blockly-Aufbaus einfügen</li><li>exportierten Blockly-XML-Code bereitstellen</li><li>Anpassungen und Voraussetzungen erklären</li></ol><p>Screenshots werden im Dokumentationsprojekt hier abgelegt:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/public/images/blog/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Einbindung im Beitrag:</p><div class="language-md vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">ioBroker Blockly</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">/images/blog/mein-blockly.png</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Objekt-IDs aus Beispielen müssen immer an das eigene ioBroker-System angepasst werden.</p></div>`,38)])])}const k=i(a,[["render",l]]);export{u as __pageData,k as default};
